<?php $id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT l.*,b.full_name borrower,e.name equipment,i.asset_code FROM loans l JOIN borrowers b ON b.id=l.borrower_id JOIN equipment_items i ON i.id=l.item_id JOIN equipment e ON e.id=i.equipment_id WHERE l.id=? AND l.returned_at IS NULL");$s->execute([$id]);$l=$s->fetch();if(!$l)redirect('?page=loans');$error='';verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$condition=$_POST['condition_label']??'';$status=$_POST['item_status']??'';$date=$_POST['returned_at']??'';if($condition==='Damaged')$status='Under Repair';elseif($condition==='Needs inspection')$status='Awaiting Inspection';if(!in_array($condition,['Good','Fair','Needs inspection','Damaged'],true)||!in_array($status,['Available','Awaiting Inspection','Under Repair'],true)||!preg_match('/^\d{4}-\d\d-\d\d$/',$date)||$date>date('Y-m-d'))$error='Choose a valid return date, condition and item status.';else{$pdo->beginTransaction();$q=$pdo->prepare('UPDATE loans SET returned_at=?,return_condition=?,return_notes=?,returned_by=? WHERE id=? AND returned_at IS NULL');$q->execute([$date,$condition,trim($_POST['return_notes']??''),user()['id'],$id]);if(!$q->rowCount()){$pdo->rollBack();$error='This loan was already returned.';}else{$q=$pdo->prepare('UPDATE equipment_items SET status=?,condition_label=? WHERE id=?');$q->execute([$status,$condition,$l['item_id']]);$q=$pdo->prepare('INSERT INTO return_records(loan_id,returned_by,returned_at,condition_label,notes) VALUES(?,?,?,?,?)');$q->execute([$id,user()['id'],$date,$condition,trim($_POST['return_notes']??'')]);log_activity($pdo,'Processed equipment return','loan',$id);$pdo->commit();flash('Return recorded. Equipment status updated.');redirect('?page=loans');}}}layout_start('Process return','loans'); ?><div class="page-heading"><div><a class="back-link" href="?page=loans">← Active loans</a><h1>Process equipment return</h1><p class="muted">Record the item's condition before putting it back into circulation.</p></div></div><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif; ?><section class="panel form-panel"><div class="callout"><strong><?=h($l['equipment'])?> · <?=h($l['asset_code'])?></strong><span>Borrower: <?=h($l['borrower'])?> · Due <?=date('j M Y',strtotime($l['due_date']))?></span></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Actual return date<input type="date" name="returned_at" value="<?=date('Y-m-d')?>" max="<?=date('Y-m-d')?>" required></label><label>Condition on return<select name="condition_label"><?php foreach(['Good','Fair','Needs inspection','Damaged'] as $v): ?><option><?=$v?></option><?php endforeach; ?></select></label><label class="span-two">New availability status<select name="item_status"><option value="Available">Available · ready to lend</option><option value="Awaiting Inspection">Awaiting inspection</option><option value="Under Repair">Under repair</option></select><small>A damaged item is automatically sent Under Repair; an item marked Needs inspection is held for inspection.</small></label><label class="span-two">Return notes<textarea name="return_notes" rows="3"></textarea></label><div class="form-actions span-two"><a class="button ghost" href="?page=loans">Cancel</a><button class="button primary">Record return</button></div></form></section><?php layout_end();
